{
  "probability": 0.98,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Anchor on the IOM Missing Migrants Project counts for the Central Mediterranean route to establish the reference class.",
    "Early-2026 pace (606 deaths by February 24) makes a path to 900 deaths by end-March plausible but not guaranteed.",
    "Bayesian synthesis yields a calibrated posterior of 0.98, incorporating both high base-rate risk and pace, with uncertainty from data gaps and policy effects."
  ],
  "confidence": "high",
  "narrative": "Using the Central Mediterranean reference class, the observed pace through February 2026 supports a plausible surge to 900 deaths by end-March. The combination of a historically deadly corridor and the early-month pace justifies a high-calibration posterior, though reporting gaps and policy changes keep some uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.8,
      "basis": "Reference class anchored on IOM Missing Migrants Project counts for Mediterranean deaths (Central Mediterranean route) and the observed early-2026 pace."
    },
    "factor_updates": [
      {
        "factor": "March 2026 pace and seasonal timing",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by Feb 24 imply ~294 more in March to hit 900; March has historically high mortality along the corridor, boosting the chance."
      },
      {
        "factor": "High historical base-rate risk for the Mediterranean corridor",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Past years show thousands of deaths (e.g., ~2,108 in 2025; ~2,452 in 2024), indicating persistent risk that supports reaching 900 early in 2026."
      },
      {
        "factor": "Data gaps and underreporting in IOM data",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "IOM/UN note access and funding constraints can lead to undercounting, which could temper the observed total toward 900."
      },
      {
        "factor": "Weather/sea-state favorable for crossings",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Calm seas and favorable conditions can increase crossing attempts and fatalities, raising the likelihood of accumulating 900 deaths by March."
      },
      {
        "factor": "SAR capacity and policy environment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Enhanced rescue capacity or stricter enforcement could reduce fatalities, moderating the chance of hitting 900 within the window."
      }
    ],
    "synthesis_rationale": "Starting from a credible anchor (0.80) for the central Mediterranean reference class, the factors collectively push probability upward (pace, base-rate) but are tempered by data gaps and policy/rescue dynamics. Correlations among pace, seasonality, and undercount risk reduce the effective independence of updates, leading to a high-calibration posterior of 0.98 with a reasonably narrow range."
  }
}

{
  "probability": 0.98,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "606 deaths by Feb 24, 2026 implies a nontrivial March/April tally under a high base-rate regime.",
    "Historical annual tolls (around 2,100–2,452 for 2024–2025) support the plausibility of crossing 900 by end-March/early-April if pace continues.",
    "Data gaps and potential undercount, plus policy and SAR factors, inject uncertainty; the posterior is high but not certain."
  ],
  "confidence": "high",
  "narrative": "Early-2026 data show a high death pace in the Mediterranean, with 606 deaths by late February; given seasonal dynamics and the historical scale, hitting 900 by end-March/early-April is very plausible. However, reporting gaps and variable rescue capacity keep the outcome uncertain, preventing a perfect forecast.",
  "justification": {
    "anchor": {
      "probability": 0.80,
      "basis": "Reference class anchored on Central Mediterranean fatalities with historically large annual tolls; 606 by Feb 2026 provides a strong starting point for a March/April update."
    },
    "factor_updates": [
      {
        "factor": "March 2026 pace and seasonal timing",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Reaching 294 more deaths in March would imply about 100 per week, which is plausible given March's historically high crossing activity."
      },
      {
        "factor": "High historical base-rate risk for the Mediterranean corridor",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "2024 and 2025 totals (2,452 and 2,108) demonstrate persistent high risk along this corridor."
      },
      {
        "factor": "Data gaps and underreporting in IOM data",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "IOM/UN cautions about undercounting; actual toll could be higher or uncertain, which affects the 900-by-April target."
      },
      {
        "factor": "Weather/sea-state favorable for crossings",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Calmer seas can increase crossing attempts and fatalities, contributing to the tally."
      },
      {
        "factor": "SAR capacity and policy environment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Enhanced rescue or stricter controls could reduce fatalities and slow the count."
      }
    ],
    "synthesis_rationale": "The net effect leans upward due to strong base-rate risk and a solid early-2026 pace; however, data gaps and policy/SAR dynamics introduce downward pressure and uncertainty. The posterior 0.98 reflects emphasis on high base-rate signals and near-term pace, with calibrated range acknowledging possible undercount and reporting delays."
  }
}

{
  "probability": 0.68,
  "range_low": 0.58,
  "range_high": 0.78,
  "summary": [
    "606 deaths by Feb 24, 2026 imply momentum toward 900 by end-March if the pace persists.",
    "Historical tolls on the Central Mediterranean route (roughly 2,100–2,452 per year) support the possibility of reaching 900 within a few weeks, but uncertainty remains due to data gaps.",
    "Key sources of uncertainty include underreporting, SAR capacity/policy shifts, and weather conditions that could shift the trajectory either way."
  ],
  "confidence": "medium",
  "narrative": "Using the IOM Missing Migrants project as anchor, the observed pace through February 2026 makes a March surge plausible but not guaranteed. The strong historical baseline and spring conditions tilt upward, while reporting gaps and policy changes temper the forecast; the calibrated probability sits around 68% with a ~0.58–0.78 range.",
  "justification": {
    "anchor": {
      "probability": 0.85,
      "basis": "Reference class: Mediterranean migrant deaths per calendar year on the Central Mediterranean route; early-2026 pace (606 deaths by Feb 24) supports a high baseline anchor probability."
    },
    "factor_updates": [
      {
        "factor": "March 2026 pace and seasonal timing",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by Feb 24 implies the calendar-month March would need about 294 more; historical March activity in the corridor has yielded sizable mortality, indicating upward pressure."
      },
      {
        "factor": "High historical base-rate risk for the Mediterranean corridor",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Past years show ~2,100–2,452 deaths/year; persistent risk makes a 900-count by April plausible, especially with a high start to 2026."
      },
      {
        "factor": "Data gaps and underreporting in IOM data",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Underreporting or verification challenges could mean observed counts understate the true toll, potentially limiting or distorting the 900-count signal."
      },
      {
        "factor": "Weather/sea-state favorable for crossings",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Calm seas enable more crossings and fatalities; a favorable pattern in March could push counts higher."
      },
      {
        "factor": "SAR capacity and policy environment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greater rescue capacity can reduce fatalities; policy tightening can suppress crossing attempts; both create downward pressure on observed deaths."
      }
    ],
    "synthesis_rationale": "Starting from an anchor around 0.85, the combined, uneven updates give mixed pressure: two upward factors with moderate-to-strong weight, and two downward factors with moderate weight, with data gaps potentially both masking or delaying counts. Calibration favors a probability in the mid-to-upper range rather than a near-certainty, producing a final estimate near 0.68 with a plausible 0.58–0.78 range, acknowledging substantial uncertainty due to reporting gaps and future conditions."
  }
}
